#!/usr/bin/env python3
"""Derive all numeric result tables from the archived measurement summaries."""
from pathlib import Path
import json,statistics as st,gzip,collections,math
D=Path(__file__).parent
read=lambda p:json.loads((D/p).read_text())
meta=read('metadata.json')
def validate(raw_path,summary_path,pair=True):
 rows=[json.loads(line) for line in gzip.decompress((D/raw_path).read_bytes()).decode().splitlines()]
 grouped=collections.defaultdict(lambda:collections.defaultdict(list))
 for x in rows:grouped[x['case']][x['engine']].append(x['elapsed_ns']/x['count'])
 for x in read(summary_path):
  values={k:st.median(v) for k,v in grouped[x['case']].items()}
  if pair:
   a=values.pop('baseline');b=next(iter(values.values()))
   assert math.isclose(x['baseline_ns'],a,rel_tol=1e-12)
   assert math.isclose(x['candidate_ns'],b,rel_tol=1e-12)
   assert math.isclose(x['change_pct'],(b/a-1)*100,rel_tol=1e-12,abs_tol=1e-12)
  else:
   for k,v in values.items():assert math.isclose(x[k],v,rel_tol=1e-12)
 assert set(grouped)=={x['case'] for x in read(summary_path)}
for v in meta['variants']:
 base='screen/'+v['path']+'/';validate(base+'windows.jsonl.gz',base+'summary.json')
for n in [1,2,3]:
 base=f'confirmation/run-{n}/';validate(base+'windows.jsonl.gz',base+'summary.json')
 validate(f'ox-driver/run-{n}.jsonl.gz',f'ox-driver/run-{n}-summary.json',False)
lines=['# Ox-inspired optimization results','','Generated by `make-results.py`. Negative change means less elapsed time.','','## Retained production source','','Each row reports the median per-process median time and the median paired change. The range shows the three paired process results, not a confidence interval.','','| Case | Main (µs) | Candidate (µs) | Change | Run range |','|---|---:|---:|---:|---:|']
runs=[{x['case']:x for x in read(f'confirmation/run-{n}/summary.json')} for n in [1,2,3]]
for name in runs[0]:
 a=[r[name] for r in runs];lo=min(x['change_pct'] for x in a);hi=max(x['change_pct'] for x in a)
 lines.append(f"| {name} | {st.median(x['baseline_ns'] for x in a)/1000:.3f} | {st.median(x['candidate_ns'] for x in a)/1000:.3f} | {st.median(x['change_pct'] for x in a):+.1f}% | {lo:+.1f}…{hi:+.1f}% |")
lines+=['','## Independent screening','','One short process pair per variant; useful for screening, not final claims. All variants passed the frozen-output checks. Worst increase includes tiny and empty controls and may be noise.','','| Variant | Large CM | Plain | Code | Headings | Late marker | Worst increase | Decision |','|---|---:|---:|---:|---:|---:|---:|---|']
decisions={'nibble-classify':'Superseded by direct lane location','nibble-locate':'Retain, with shared classifier and endian fallback','borrow-content':'Superseded by contiguous borrowing','borrow-contiguous':'Retain; preserve profiling and reset source ranges','code-info-borrow':'Retain','headings-flat':'Reject: no stable gain for extra complexity','headings-presize':'Replace extra scan with parser count','headings-count':'Retain','heading-cache':'Reject: unique-heading regression','escape-swar':'Reject: prose/long-code regressions','output2x':'Reject: extra capacity without clear gain','first-marker':'Reject: common mixed inputs regress','direct-text-event':'Retain in confirmed combination'}
for v in meta['variants']:
 a=read('screen/'+v['path']+'/summary.json');r={x['case']:x['change_pct'] for x in a}
 vals=' | '.join(f'{r[k]:+.1f}%' for k in ['ox-large-cm','plain','code','headings','late-marker']);label=v['path'];decision=decisions.get(v['name'],'Combination screen; see production confirmation')
 lines.append(f"| {label} | {vals} | {max(r.values()):+.1f}% | {decision} |")
lines+=['','## Allocations','','Calls include allocation and reallocation requests. Bytes are cumulative requested sizes, not peak or retained memory. Separate instrumented binaries; these counters never run in the timed binaries. Reused-renderer rows exclude renderer creation and use warmed scratch.','','| Case | Main calls | Candidate calls | Main requested bytes | Candidate requested bytes |','|---|---:|---:|---:|---:|']
a=read('allocation/baseline.json');b=read('allocation/candidate.json')
for x,y in zip(a,b):
 assert x['case']==y['case']
 lines.append(f"| {x['case']} | {x['calls']} | {y['calls']} | {x['requested_bytes']} | {y['requested_bytes']} |")
lines+=['','## Fresh comparison with Ox Content','','Native Markdown→owned HTML, identical inputs and selected syntax flags, system allocator, generic target. Ox uses its intended source-sized arena. Heading IDs stay enabled; incidental HTML whitespace and IDs are normalized only for the comparison check, outside timing. Ferromark before/after output must match exactly. Ratio below 1 means the candidate takes less time than Ox.','','| Case | Main (µs) | Candidate (µs) | Ox (µs) | Candidate / Ox |','|---|---:|---:|---:|---:|']
runs=[{x['case']:x for x in read(f'ox-driver/run-{n}-summary.json')} for n in [1,2,3]]
for name in runs[0]:
 a=[r[name] for r in runs];vals=' | '.join(f"{st.median(x[k] for x in a)/1000:.3f}" for k in ['baseline','candidate','ox'])
 lines.append(f"| {name} | {vals} | {st.median(x['candidate']/x['ox'] for x in a):.3f}× |")
excluded=[x['case'] for x in read('ox-driver/verification.json') if not x['normalized_equal']]
lines+=['',('Excluded for differing normalized output: '+', '.join(excluded)) if excluded else 'Every selected Ox comparison passed the documented output check.','']
(D/'RESULTS.md').write_text('\n'.join(lines))
